import {
    Fragment, useEffect, useId, useLayoutEffect, useMemo, useRef, useState,
    type ReactNode,
} from "react";
import { ActionBar } from "./action-bar";
import { Button } from "./button";
import { Checkbox } from "./checkbox";
import { Input } from "./input";
import { NativeSelect } from "./native-select";
import { Pagination } from "./pagination";
import { Table, TableCell, TableHead, type TableProps } from "./table";
import { cn } from "./utils";
import type { QueryField, QueryNode } from "./query-builder";
import { assertWorkViewConfig } from "./work-view";
import type { WorkViewConfig, WorkViewSort } from "./work-view";

type DataTableValue = string | number | null | undefined;

type DataTableColumn<Row> = {
    id: string;
    header: string;
    cell: (row: Row) => ReactNode;
    sortValue?: (row: Row) => string | number | null | undefined;
    sortable?: boolean;
    filterType?: QueryField["type"];
    filterValue?: (row: Row) => DataTableValue;
    groupValue?: (row: Row) => DataTableValue;
    editValue?: (row: Row) => string;
    editOptions?: readonly { value: string; label: string }[];
    className?: string;
};

type DataTableFilter<Row> = {
    label: string;
    getValue: (row: Row) => string;
    options: readonly { value: string; label: string }[];
};

type DataTableRemoteFilter = Pick<DataTableFilter<unknown>,
    "label" | "options">;

type DataTableBaseProps<Row> = {
    caption: string;
    rows: readonly Row[];
    columns: readonly DataTableColumn<Row>[];
    getRowId: (row: Row) => string;
    getRowLabel?: (row: Row) => string;
    getSearchText?: (row: Row) => string;
    searchPlaceholder?: string;
    defaultPageSize?: number;
    pageSizeOptions?: readonly number[];
    selectable?: boolean;
    getRowChildren?: (row: Row) => readonly Row[];
    workView?: WorkViewConfig;
    workViewId?: string;
    /** Receives the complete filter and multi-sort config. When paired with
     * remote rows, consumers use this value for server filtering and sorting;
     * remote.onViewChange receives the compatibility primary sort and page. */
    onWorkViewChange?: (config: WorkViewConfig) => void;
    onCellSave?: (
        row: Row, columnId: string, value: string,
    ) => void | Promise<void>;
    renderActions?: (
        selectedRows: readonly Row[], clearSelection: () => void,
    ) => ReactNode;
    renderRowDetails?: (row: Row) => ReactNode;
    emptyMessage?: string;
    density?: "compact" | "standard" | "comfortable";
    striped?: boolean;
    appearance?: TableProps["appearance"];
    className?: string;
};

type DataTableProps<Row> = DataTableBaseProps<Row> & (
    { filter?: DataTableFilter<Row>; remote?: undefined } |
    { filter?: DataTableRemoteFilter; remote: DataTableRemote }
);

type DataTableSort = { id: string; direction: "ascending" | "descending" };

type DataTableView = {
    query: string;
    filterValue: string;
    sort: DataTableSort | null;
    page: number;
    pageSize: number;
};

type DataTableRemote = {
    view: DataTableView;
    totalItems: number;
    onViewChange: (view: DataTableView) => void;
    searchable?: boolean;
    status?: "ready" | "loading" | "error";
    errorMessage?: string;
    onRetry?: () => void;
};

type DataTableTreeRow<Row> = {
    row: Row;
    id: string;
    depth: number;
    children: readonly DataTableTreeRow<Row>[];
};

type DataTableDisplayItem<Row> =
    | { kind: "group"; id: string; label: string }
    | { kind: "row"; item: DataTableTreeRow<Row> };

function isMissingSortValue(value: string | number | null | undefined) {
    return value == null ||
        (typeof value === "number" && !Number.isFinite(value));
}

function compareSortValues(
    first: string | number | null | undefined,
    second: string | number | null | undefined,
) {
    const a = typeof first === "number" && !Number.isFinite(first)
        ? null : first;
    const b = typeof second === "number" && !Number.isFinite(second)
        ? null : second;
    if (a == null) return b == null ? 0 : 1;
    if (b == null) return -1;
    if (typeof a === "number" && typeof b === "number") return a - b;
    const aText = String(a).toLowerCase();
    const bText = String(b).toLowerCase();
    return aText < bText ? -1 : aText > bText ? 1 : 0;
}

function compareWorkViewSortValues(
    first: string | number | null | undefined,
    second: string | number | null | undefined,
    direction: WorkViewSort["direction"],
) {
    const compared = compareSortValues(first, second);
    if (isMissingSortValue(first) || isMissingSortValue(second)) {
        return compared;
    }
    return direction === "descending" ? -compared : compared;
}

function matchesWorkViewNode<Row>(
    node: QueryNode,
    row: Row,
    columns: readonly DataTableColumn<Row>[],
): boolean {
    if (node.kind === "group") {
        if (node.children.length === 0) return true;
        const matches = node.children.map((child) =>
            matchesWorkViewNode(child, row, columns),
        );
        return node.combinator === "all"
            ? matches.every(Boolean) : matches.some(Boolean);
    }

    const column = columns.find((item) => item.id === node.fieldId);
    if (!column?.filterValue || !column.filterType) {
        throw new Error(`WorkView filter column is unavailable: ${node.fieldId}`);
    }
    const value = column.filterValue(row);
    const empty = value == null || value === "";
    if (node.operator === "is-empty") return empty;
    if (node.operator === "is-not-empty") return !empty;
    if (empty) return false;

    if (node.operator === "contains") {
        if (column.filterType !== "text") {
            throw new Error("WorkView contains requires a text column.");
        }
        return String(value).toLowerCase().includes(
            node.value.toLowerCase(),
        );
    }

    let comparison: number;
    if (column.filterType === "number") {
        const actual = Number(value);
        const expected = Number(node.value);
        if (!Number.isFinite(actual) || !Number.isFinite(expected)) {
            return false;
        }
        comparison = actual - expected;
    } else {
        const actual = String(value);
        const expected = node.value;
        comparison = actual < expected ? -1 : actual > expected ? 1 : 0;
        if (column.filterType === "text" &&
            (node.operator === "equals" ||
                node.operator === "not-equals")) {
            comparison = actual.toLowerCase() <
                expected.toLowerCase() ? -1 :
                actual.toLowerCase() > expected.toLowerCase()
                    ? 1 : 0;
        }
    }
    if (node.operator === "equals") return comparison === 0;
    if (node.operator === "not-equals") return comparison !== 0;
    if (node.operator === "greater-than") return comparison > 0;
    if (node.operator === "less-than") return comparison < 0;
    return false;
}

function flattenDataTableRows<Row>(
    rows: readonly DataTableTreeRow<Row>[],
): DataTableTreeRow<Row>[] {
    return rows.flatMap((item) => [item,
        ...flattenDataTableRows(item.children),
    ]);
}

function assertWorkViewFilterColumns<Row>(
    node: QueryNode,
    columns: readonly DataTableColumn<Row>[],
) {
    if (node.kind === "group") {
        node.children.forEach((child) =>
            assertWorkViewFilterColumns(child, columns),
        );
        return;
    }
    const column = columns.find((item) => item.id === node.fieldId);
    if (!column?.filterType || !column.filterValue) {
        throw new Error(
            `WorkView filter column is unavailable: ${node.fieldId}`,
        );
    }
    if (node.operator === "contains" && column.filterType !== "text") {
        throw new Error("WorkView contains requires a text column.");
    }
    if ((node.operator === "greater-than" ||
        node.operator === "less-than") &&
        column.filterType !== "number" && column.filterType !== "date") {
        throw new Error("WorkView comparisons require number or date columns.");
    }
    if ((node.operator === "is-empty" ||
        node.operator === "is-not-empty") && node.value !== "") {
        throw new Error("WorkView empty filters cannot have a value.");
    }
    if (column.filterType === "number" &&
        node.operator !== "is-empty" &&
        node.operator !== "is-not-empty" &&
        (!Number.isFinite(Number(node.value)) || node.value.trim() === "")) {
        throw new Error("WorkView numeric filters need a finite value.");
    }
}

/** Shares table filter/sort semantics with alternate views of the same rows. */
function filterAndSortTableRows<Row>(rows: readonly Row[],
    columns: readonly DataTableColumn<Row>[], config: WorkViewConfig) {
    assertWorkViewConfig(config, columns.map((column) => column.id));
    assertWorkViewFilterColumns(config.filter, columns);
    return rows.filter((row) => matchesWorkViewNode(config.filter, row, columns))
        .map((row, index) => ({ row, index })).sort((a, b) => {
            for (const sort of config.sorts) {
                const column = columns.find((item) => item.id === sort.columnId);
                if (!column?.sortValue) throw new Error("Sort column needs sortValue.");
                const result = compareWorkViewSortValues(
                    column.sortValue(a.row), column.sortValue(b.row),
                    sort.direction,
                );
                if (result) return result;
            }
            return a.index - b.index;
        }).map(({ row }) => row);
}

function DataTable<Row>({
    caption, rows, columns, getRowId, getRowLabel, getSearchText,
    searchPlaceholder = "검색", filter, defaultPageSize = 10,
    pageSizeOptions = [10, 25, 50], selectable = false,
    getRowChildren, workView, workViewId, onWorkViewChange, onCellSave,
    renderActions, renderRowDetails,
    emptyMessage = "표시할 항목이 없습니다.", remote,
    density = "standard", striped = false, appearance = "lined",
    className,
}: DataTableProps<Row>) {
    const searchId = useId();
    const filterId = useId();
    const detailsId = useId();
    const [localView, setLocalView] = useState<DataTableView>(() => ({
        query: "", filterValue: "", sort: null,
        page: 1, pageSize: defaultPageSize,
    }));
    const remoteView = useRef(remote?.view);
    remoteView.current = remote?.view;
    const isRemote = remote !== undefined;
    const { query, filterValue, sort, page, pageSize } =
        remote?.view ?? localView;
    if (remote && (!Number.isSafeInteger(remote.totalItems) ||
        remote.totalItems < 0 || !Number.isSafeInteger(page) || page < 1 ||
        !Number.isSafeInteger(pageSize) || pageSize < 1)) {
        throw new Error("DataTable remote view requires valid page, " +
            "pageSize, and totalItems values");
    }
    const [selectedIds, setSelectedIds] = useState<Set<string>>(
        () => new Set(),
    );
    const [expandedIds, setExpandedIds] = useState<Set<string>>(
        () => new Set(),
    );
    const [expandedChildrenIds, setExpandedChildrenIds] = useState<Set<string>>(
        () => new Set(),
    );
    const [editingCell, setEditingCell] = useState<{
        rowId: string;
        columnId: string;
        value: string;
        error: string | null;
        saving: boolean;
    } | null>(null);
    const editButtonRefs = useRef(new Map<string, HTMLButtonElement>());
    const previousEditingKey = useRef<string | null>(null);
    const tableRegion = useRef<HTMLDivElement>(null);
    const activeFilterValue = filterValue && filter?.options.some(
        (option) => option.value === filterValue,
    ) ? filterValue : "";

    if (workViewId !== undefined &&
        (typeof workViewId !== "string" || !workViewId.trim() || !workView)) {
        throw new Error("DataTable workViewId requires a nonempty workView.");
    }
    if (columns.some((column) => column.editOptions &&
        (!column.editValue || !column.editOptions.length ||
            new Set(column.editOptions.map((option) => option.value)).size !==
                column.editOptions.length ||
            column.editOptions.some((option) =>
                typeof option.value !== "string" ||
                typeof option.label !== "string" || !option.label.trim(),
            )))) {
        throw new Error("DataTable cell editors need unique values and labels.");
    }

    if (workView) {
        assertWorkViewConfig(workView, columns.map((column) => column.id));
        if (columns.some((column) => workView.sorts.some((sortRule) =>
            sortRule.columnId === column.id && !remote &&
            !column.sortValue,
        ))) {
            throw new Error("WorkView sort columns need sortValue.");
        }
        const groupColumn = columns.find((column) =>
            column.id === workView.groupBy,
        );
        if (workView.groupBy &&
            !groupColumn?.groupValue && !groupColumn?.filterValue) {
            throw new Error("WorkView group columns need a value callback.");
        }
        if (!remote) assertWorkViewFilterColumns(workView.filter, columns);
    }

    const editingKey = editingCell
        ? JSON.stringify([editingCell.rowId, editingCell.columnId]) : null;
    useLayoutEffect(() => {
        if (editingKey === null && previousEditingKey.current !== null) {
            editButtonRefs.current.get(previousEditingKey.current)?.focus();
        }
        previousEditingKey.current = editingKey;
    }, [editingKey]);

    useEffect(() => {
        if (!isRemote && filterValue && !activeFilterValue) {
            setLocalView((current) => ({ ...current, filterValue: "" }));
        }
    }, [isRemote, filterValue, activeFilterValue]);

    const remoteViewKey = remote ? JSON.stringify([
        query, filterValue, sort?.id, sort?.direction, page, pageSize,
    ]) : null;
    useEffect(() => {
        if (remoteViewKey !== null ||
            remote?.status === "loading" || remote?.status === "error") {
            setSelectedIds((current) => current.size > 0
                ? new Set() : current);
            setExpandedIds((current) => current.size > 0
                ? new Set() : current);
            setExpandedChildrenIds((current) => current.size > 0
                ? new Set() : current);
        }
    }, [remoteViewKey, remote?.status]);

    function changeView(patch: Partial<DataTableView>) {
        if (remote) {
            const next = { ...(remoteView.current ?? remote.view), ...patch };
            remoteView.current = next;
            remote.onViewChange(next);
        } else {
            setLocalView((current) => ({ ...current, ...patch }));
        }
    }

    const tableTree = useMemo(() => {
        const queryNeedle = query.trim().toLowerCase();
        const seenIds = new Set<string>();

        function matchesLegacyFilters(row: Row) {
            return (!queryNeedle || !getSearchText ||
                getSearchText(row).toLowerCase().includes(queryNeedle)) &&
                (!activeFilterValue || !filter ||
                    ("getValue" in filter &&
                        filter.getValue(row) === activeFilterValue));
        }

        function sortRows(tree: DataTableTreeRow<Row>[]) {
            const sortRules: readonly WorkViewSort[] =
                workView && !isRemote ? workView.sorts :
                    !isRemote && !workView && sort ? [{
                        columnId: sort.id,
                        direction: sort.direction,
                    }] : [];
            if (sortRules.length === 0) return tree;
            return tree.map((item, index) => ({ item, index })).sort(
                (first, second) => {
                    for (const rule of sortRules) {
                        const column = columns.find((candidate) =>
                            candidate.id === rule.columnId,
                        );
                        const firstValue = column?.sortValue?.(first.item.row);
                        const secondValue = column?.sortValue?.(second.item.row);
                        const compared = compareWorkViewSortValues(
                            firstValue, secondValue, rule.direction,
                        );
                        if (compared !== 0) return compared;
                    }
                    return first.index - second.index;
                },
            ).map(({ item }) => item);
        }

        function buildTree(
            source: readonly Row[], depth: number,
        ): DataTableTreeRow<Row>[] {
            const matches: DataTableTreeRow<Row>[] = [];
            for (const row of source) {
                const rowId = getRowId(row);
        if ((getRowChildren || workView) && seenIds.has(rowId)) {
                    throw new Error("DataTable row IDs must be unique.");
                }
                seenIds.add(rowId);
                const children = buildTree(
                    getRowChildren?.(row) ?? [], depth + 1,
                );
                const passes = isRemote || (
                    matchesLegacyFilters(row) &&
                    (!workView || matchesWorkViewNode(
                        workView.filter, row, columns,
                    ))
                );
                if (passes || children.length > 0) {
                    matches.push({ row, id: rowId, depth, children });
                }
            }
            return sortRows(matches);
        }

        return buildTree(rows, 0);
    }, [rows, query, activeFilterValue, getSearchText, filter, columns,
        sort, workView, getRowId, getRowChildren, isRemote]);

    const visibleRows = tableTree.map((item) => item.row);
    const workViewKey = workView ? JSON.stringify(workView) : null;
    useEffect(() => {
        if (workViewKey !== null) {
            if (remote && page !== 1) changeView({ page: 1 });
            if (!remote) {
                setLocalView((current) => current.page === 1
                    ? current : { ...current, page: 1 });
            }
        }
    }, [workViewKey]);
    const workViewSelectionKey = workView ? JSON.stringify([
        workViewId ?? null,
        workView.filter,
        query,
        filterValue,
    ]) : null;
    useEffect(() => {
        if (workViewSelectionKey !== null) {
            setSelectedIds((current) => current.size > 0
                ? new Set() : current);
            setExpandedChildrenIds((current) => current.size > 0
                ? new Set() : current);
        }
    }, [workViewSelectionKey]);
    useEffect(() => {
        const availableIds = new Set(
            workView || getRowChildren
                ? flattenDataTableRows(tableTree).map((item) => item.id)
                : rows.map(getRowId),
        );
        setSelectedIds((current) => {
            const next = new Set(
                [...current].filter((id) => availableIds.has(id)),
            );
            return next.size === current.size ? current : next;
        });
        setExpandedIds((current) => {
            const next = new Set(
                [...current].filter((id) => availableIds.has(id)),
            );
            return next.size === current.size ? current : next;
        });
        setExpandedChildrenIds((current) => {
            const next = new Set(
                [...current].filter((id) => availableIds.has(id)),
            );
            return next.size === current.size ? current : next;
        });
    }, [tableTree, rows, getRowId, workView, getRowChildren]);

    const validPageSize = Number.isInteger(pageSize) && pageSize > 0
        ? pageSize : 1;
    const pageCount = Math.max(
        1, Math.ceil((remote?.totalItems ?? visibleRows.length) /
            validPageSize),
    );
    useEffect(() => {
        if (!isRemote) {
            setLocalView((current) => current.page > pageCount
                ? { ...current, page: pageCount } : current);
        }
    }, [pageCount, isRemote]);
    const currentPage = Math.min(page, pageCount);
    const pageTree = remote
        ? remote.status === "loading" || remote.status === "error"
            ? [] : tableTree
        : tableTree.slice(
            (currentPage - 1) * validPageSize, currentPage * validPageSize,
        );
    const pageRows = pageTree.map((item) => item.row);
    const pageSelectableRows = workView || getRowChildren
        ? flattenDataTableRows(pageTree).map((item) => item.row)
        : pageRows;
    const selectableRows = workView || getRowChildren
        ? flattenDataTableRows(remote ? pageTree : tableTree).map(
            (item) => item.row,
        )
        : remote ? pageRows : rows;
    const selectedRows = selectableRows.filter(
        (row) => selectedIds.has(getRowId(row)),
    );
    const selectedOnPage = pageSelectableRows.filter(
        (row) => selectedIds.has(getRowId(row)),
    ).length;
    const displayColumns = workView
        ? workView.columnOrder
            .filter((id) => workView.visibleColumns.includes(id))
            .map((id) => columns.find((column) => column.id === id)!)
        : [...columns];
    const controlColumnCount = (getRowChildren ? 1 : 0) +
        (renderRowDetails ? 1 : 0) + (selectable ? 1 : 0);
    const columnCount = displayColumns.length + controlColumnCount;

    const pinnedLeft = workView?.pinnedColumns.left.filter((id) =>
        displayColumns.some((column) => column.id === id),
    ) ?? [];
    const pinnedRight = workView?.pinnedColumns.right.filter((id) =>
        displayColumns.some((column) => column.id === id),
    ) ?? [];
    const columnStyles = new Map<string, {
        width?: number;
        position?: "sticky";
        left?: number;
        right?: number;
        zIndex?: number;
    }>();
    let leftOffset = controlColumnCount * 40;
    for (const id of pinnedLeft) {
        const width = workView?.columnWidths[id] ?? 180;
        columnStyles.set(id, { width, position: "sticky",
            left: leftOffset, zIndex: 1 });
        leftOffset += width;
    }
    let rightOffset = 0;
    for (const id of [...pinnedRight].reverse()) {
        const width = workView?.columnWidths[id] ?? 180;
        columnStyles.set(id, { ...columnStyles.get(id), width,
            position: "sticky", right: rightOffset, zIndex: 1 });
        rightOffset += width;
    }
    for (const column of displayColumns) {
        const existing = columnStyles.get(column.id) ?? {};
        columnStyles.set(column.id, {
            ...existing,
            width: workView?.columnWidths[column.id] ?? existing.width,
        });
    }

    const groupedItems = useMemo(() => {
        if (!workView?.groupBy) {
            return pageTree.map((item): DataTableDisplayItem<Row> => ({
                kind: "row", item,
            }));
        }
        const column = columns.find((item) =>
            item.id === workView.groupBy,
        )!;
        const groups = new Map<string, {
            label: string;
            rows: DataTableTreeRow<Row>[];
        }>();
        for (const item of pageTree) {
            const groupValue = column.groupValue
                ? column.groupValue(item.row)
                : column.filterValue?.(item.row);
            const isEmpty = groupValue == null || groupValue === "";
            const key = isEmpty ? "empty" :
                `${typeof groupValue}:${String(groupValue)}`;
            const group = groups.get(key) ?? {
                label: `${column.header}: ${isEmpty
                    ? "값 없음" : String(groupValue)}`,
                rows: [],
            };
            group.rows.push(item);
            groups.set(key, group);
        }
        return [...groups].flatMap(([key, group]) => [
            { kind: "group" as const, id: key, label: group.label },
            ...group.rows.map((item): DataTableDisplayItem<Row> => ({
                kind: "row", item,
            })),
        ]);
    }, [pageTree, workView?.groupBy, columns, workView]);

    function togglePage(checked: boolean) {
        setSelectedIds((current) => {
            const next = new Set(current);
            pageSelectableRows.forEach((row) => {
                if (checked) next.add(getRowId(row));
                else next.delete(getRowId(row));
            });
            return next;
        });
    }

    function resetView() {
        changeView({ query: "", filterValue: "", sort: null, page: 1 });
    }

    function changeWorkView(next: WorkViewConfig) {
        onWorkViewChange?.(next);
        if (remote) {
            const primary = next.sorts[0];
            changeView({
                sort: primary ? {
                    id: primary.columnId,
                    direction: primary.direction,
                } : null,
                page: 1,
            });
        }
        else setLocalView((current) => ({ ...current, page: 1 }));
    }

    function toggleChildren(id: string) {
        setExpandedChildrenIds((current) => {
            const next = new Set(current);
            if (next.has(id)) next.delete(id);
            else next.add(id);
            return next;
        });
    }

    function clearSelection() {
        setSelectedIds(new Set());
        tableRegion.current?.focus();
    }

    function toggleDetails(id: string) {
        setExpandedIds((current) => {
            const next = new Set(current);
            if (next.has(id)) next.delete(id);
            else next.add(id);
            return next;
        });
    }

    function startCellEdit(row: Row, column: DataTableColumn<Row>) {
        if (!column.editValue || !onCellSave) return;
        const value = column.editValue(row);
        if (typeof value !== "string") {
            throw new Error("DataTable cell edit values must be strings.");
        }
        setEditingCell({
            rowId: getRowId(row),
            columnId: column.id,
            value,
            error: null,
            saving: false,
        });
    }

    async function saveCellEdit(row: Row, column: DataTableColumn<Row>) {
        const current = editingCell;
        if (!current || current.rowId !== getRowId(row) ||
            current.columnId !== column.id || current.saving || !onCellSave) {
            return;
        }
        setEditingCell({ ...current, saving: true, error: null });
        try {
            await onCellSave(row, column.id, current.value);
            setEditingCell((latest) => latest === current ||
                (latest?.rowId === current.rowId &&
                    latest.columnId === current.columnId) ? null : latest);
        } catch (error) {
            const message = error instanceof Error && error.message.trim()
                ? error.message : "셀 변경을 저장하지 못했습니다.";
            setEditingCell((latest) => latest?.rowId === current.rowId &&
                latest.columnId === current.columnId
                ? { ...latest, saving: false, error: message } : latest);
        }
    }

    function renderRow(item: DataTableTreeRow<Row>, index: number): ReactNode {
        const { row, id } = item;
        const label = getRowLabel?.(row) ?? id;
        const expanded = expandedIds.has(id);
        const expandedChildren = expandedChildrenIds.has(id);
        const panelId = `${detailsId}-row-${encodeURIComponent(id)}`;
        const detailLabel = `${label} 상세 ${expanded ? "접기" : "펼치기"}`;
        return (
            <Fragment key={id}>
                <tr data-row-id={getRowChildren || workView ? id : undefined}
                    data-depth={getRowChildren || workView
                        ? item.depth : undefined}
                    className={striped && index % 2 === 1
                        ? "bg-surface-subtle" : undefined}>
                    {getRowChildren && (
                        <TableCell className="w-10">
                            {item.children.length > 0 ? (
                                <button type="button"
                                    data-slot="nested-row-disclosure"
                                    aria-label={`${label} 하위 행 ${expandedChildren
                                        ? "접기" : "펼치기"}`}
                                    aria-expanded={expandedChildren}
                                    className={
                                        "grid size-7 place-items-center " +
                                        "rounded-sm text-foreground " +
                                        "hover:bg-surface-subtle " +
                                        "focus-visible:outline-2 " +
                                        "focus-visible:outline-focus"
                                    }
                                    onClick={() => toggleChildren(id)}>
                                    <span aria-hidden="true">
                                        {expandedChildren ? "−" : "+"}
                                    </span>
                                </button>
                            ) : <span aria-hidden="true" className="block size-7" />}
                        </TableCell>
                    )}
                    {renderRowDetails && (
                        <TableCell>
                            <button type="button" data-slot="row-disclosure"
                                aria-label={detailLabel}
                                aria-expanded={expanded}
                                aria-controls={expanded ? panelId : undefined}
                                className={
                                    "grid size-7 place-items-center " +
                                    "rounded-sm text-foreground " +
                                    "hover:bg-surface-subtle " +
                                    "focus-visible:outline-2 " +
                                    "focus-visible:outline-focus"
                                }
                                onClick={() => toggleDetails(id)}>
                                <span aria-hidden="true">
                                    {expanded ? "−" : "+"}
                                </span>
                            </button>
                        </TableCell>
                    )}
                    {selectable && (
                        <TableCell>
                            <Checkbox aria-label={`${label} 선택`}
                                checked={selectedIds.has(id)}
                                onCheckedChange={(checked) => {
                                    setSelectedIds((current) => {
                                        const next = new Set(current);
                                        if (checked === true) next.add(id);
                                        else next.delete(id);
                                        return next;
                                    });
                                }} />
                        </TableCell>
                    )}
                    {displayColumns.map((column) => {
                        const isEditing = editingCell?.rowId === id &&
                            editingCell.columnId === column.id;
                        const style = columnStyles.get(column.id);
                        return (
                            <TableCell key={column.id}
                                className={cn(column.className,
                                    style?.position && "sticky bg-surface")}
                                style={style}>
                                {isEditing && editingCell ? (
                                    <div className="grid min-w-32 gap-2">
                                        {column.editOptions ? (
                                            <NativeSelect
                                                aria-label={`${label} ${column.header} 값`}
                                                autoFocus
                                                value={editingCell.value}
                                                disabled={editingCell.saving}
                                                onChange={(event) =>
                                                    setEditingCell((current) =>
                                                        current ? { ...current,
                                                            value: event.target.value,
                                                            error: null,
                                                        } : current)}>
                                                {!column.editOptions.some((option) =>
                                                    option.value === editingCell.value,
                                                ) && <option value={editingCell.value}>
                                                    현재 값 ({editingCell.value})
                                                </option>}
                                                {column.editOptions.map((option) => (
                                                    <option key={option.value}
                                                        value={option.value}>
                                                        {option.label}
                                                    </option>
                                                ))}
                                            </NativeSelect>
                                        ) : (
                                            <Input aria-label={`${label} ${column.header} 값`}
                                                autoFocus
                                                value={editingCell.value}
                                                disabled={editingCell.saving}
                                                onChange={(event) =>
                                                    setEditingCell((current) =>
                                                        current ? { ...current,
                                                            value: event.target.value,
                                                            error: null,
                                                        } : current)}
                                                onKeyDown={(event) => {
                                                    if (event.nativeEvent.isComposing ||
                                                        event.nativeEvent.keyCode === 229) {
                                                        return;
                                                    }
                                                    if (event.key === "Enter") {
                                                        event.preventDefault();
                                                        void saveCellEdit(row, column);
                                                    } else if (event.key === "Escape") {
                                                        setEditingCell(null);
                                                    }
                                                }} />
                                        )}
                                        <div className="flex flex-wrap gap-1">
                                            <Button variant="outline"
                                                disabled={editingCell.saving}
                                                onClick={() =>
                                                    void saveCellEdit(row, column)}>
                                                {editingCell.saving
                                                    ? "저장 중…" : "저장"}
                                            </Button>
                                            <Button variant="ghost"
                                                disabled={editingCell.saving}
                                                onClick={() =>
                                                    setEditingCell(null)}>
                                                취소
                                            </Button>
                                        </div>
                                        {editingCell.error && (
                                            <p role="alert" className="m-0 text-xs text-danger">
                                                {editingCell.error}
                                            </p>
                                        )}
                                    </div>
                                ) : onCellSave && column.editValue ? (
                                    <div className="flex min-w-0 items-center gap-2">
                                        <span className="min-w-0 flex-1">
                                            {column.cell(row)}
                                        </span>
                                        <Button variant="ghost" size="icon"
                                            aria-label={`${label} ${column.header} 수정`}
                                            ref={(element) => {
                                                const key = JSON.stringify([id, column.id]);
                                                if (element) {
                                                    editButtonRefs.current.set(key, element);
                                                } else {
                                                    editButtonRefs.current.delete(key);
                                                }
                                            }}
                                            onClick={() =>
                                                startCellEdit(row, column)}>
                                            편집
                                        </Button>
                                    </div>
                                ) : column.cell(row)}
                            </TableCell>
                        );
                    })}
                </tr>
                {renderRowDetails && expanded && (
                    <tr className="bg-surface-subtle">
                        <TableCell colSpan={columnCount}>
                            <div id={panelId} className="min-w-0">
                                <span className="sr-only">{label} 상세</span>
                                {renderRowDetails(row)}
                            </div>
                        </TableCell>
                    </tr>
                )}
                {getRowChildren && expandedChildren &&
                    item.children.map((child, childIndex) =>
                        renderRow(child, childIndex),
                    )}
            </Fragment>
        );
    }

    return (
        <div className={cn("grid min-w-0 gap-3", className)}>
            <div className="flex flex-wrap items-end gap-2">
                {(getSearchText || remote?.searchable) && (
                    <div className="min-w-40 flex-1">
                        <label className="sr-only" htmlFor={searchId}>
                            {caption} 검색
                        </label>
                        <Input
                            id={searchId}
                            type="search"
                            placeholder={searchPlaceholder}
                            value={query}
                            onChange={(event) => {
                                changeView({ query: event.target.value,
                                    page: 1 });
                            }}
                        />
                    </div>
                )}
                {filter && (
                    <div className="min-w-32">
                        <label className="sr-only" htmlFor={filterId}>
                            {filter.label}
                        </label>
                        <NativeSelect
                            id={filterId}
                            value={activeFilterValue}
                            onChange={(event) => {
                                changeView({ filterValue: event.target.value,
                                    page: 1 });
                            }}
                        >
                            <option value="">{filter.label}: 전체</option>
                            {filter.options.map((option) => (
                                <option key={option.value} value={option.value}>
                                    {option.label}
                                </option>
                            ))}
                        </NativeSelect>
                    </div>
                )}
                {(getSearchText || remote?.searchable || filter || sort) && (
                    <Button variant="ghost" onClick={resetView}>
                        보기 초기화
                    </Button>
                )}
            </div>
            {selectable && selectedRows.length > 0 && (
                <ActionBar
                    aria-label="선택한 행 작업"
                    selectedCount={selectedRows.length}
                    onClear={clearSelection}
                >
                    {renderActions?.(selectedRows, clearSelection)}
                </ActionBar>
            )}
            <div role="region" aria-label={`${caption} 가로 스크롤`}
                data-ui="table-frame"
                aria-busy={remote?.status === "loading" || undefined}
                ref={tableRegion}
                tabIndex={0}
                className={
                    "min-w-0 overflow-x-auto rounded-sm " +
                    "focus-visible:outline-2 focus-visible:outline-focus"
                }>
                <Table appearance={appearance} className={cn(
                    "min-w-max",
                    density === "compact" &&
                        "[--density-row-block:var(--space-1)]",
                    density === "comfortable" &&
                        "[--density-row-block:var(--space-4)]",
                )}>
                    <caption className="sr-only">{caption}</caption>
                    <thead>
                        <tr>
                            {getRowChildren && (
                                <TableHead scope="col" className="w-10">
                                    <span className="sr-only">하위 행</span>
                                </TableHead>
                            )}
                            {renderRowDetails && (
                                <TableHead scope="col" className="w-10">
                                    <span className="sr-only">상세</span>
                                </TableHead>
                            )}
                            {selectable && (
                                <TableHead scope="col" className="w-10">
                                    <Checkbox
                                        aria-label="현재 페이지의 행 모두 선택"
                                        disabled={pageSelectableRows.length === 0}
                                        checked={selectedOnPage === 0
                                            ? false
                                            : selectedOnPage === pageSelectableRows.length
                                                ? true : "indeterminate"}
                                        onCheckedChange={(checked) =>
                                            togglePage(checked === true)}
                                    />
                                </TableHead>
                            )}
                            {displayColumns.map((column) => {
                                const configuredIndex = workView?.sorts.findIndex(
                                    (rule) => rule.columnId === column.id,
                                ) ?? -1;
                                const configuredSort = configuredIndex >= 0
                                    ? workView?.sorts[configuredIndex] : undefined;
                                const canSort = workView
                                    ? Boolean(onWorkViewChange) && (remote
                                        ? Boolean(column.sortable ||
                                            column.sortValue)
                                        : Boolean(column.sortValue))
                                    : Boolean(column.sortValue ||
                                        (remote && column.sortable));
                                const style = columnStyles.get(column.id);
                                return (
                                    <TableHead key={column.id} scope="col"
                                        aria-sort={workView
                                            ? configuredIndex === 0
                                                ? configuredSort?.direction : undefined
                                            : sort?.id === column.id
                                                ? sort.direction : undefined}
                                        className={cn(column.className,
                                            style?.position &&
                                                "sticky z-20 bg-surface")}
                                        style={{ ...style,
                                            zIndex: style?.position ? 2 : undefined }}>
                                        {canSort ? (
                                            <button type="button"
                                                data-slot="table-sort"
                                                data-sort-priority={configuredIndex >= 0
                                                    ? configuredIndex + 1 : undefined}
                                                className={
                                                    "inline-flex items-center gap-1 " +
                                                    "text-left text-foreground"
                                                }
                                                onClick={() => {
                                                    if (workView) {
                                                        const current = workView.sorts[
                                                            configuredIndex
                                                        ];
                                                        const sorts = [...workView.sorts];
                                                        if (!current) {
                                                            sorts.push({
                                                                columnId: column.id,
                                                                direction: "ascending",
                                                            });
                                                        } else if (current.direction ===
                                                            "ascending") {
                                                            sorts[configuredIndex] = {
                                                                ...current,
                                                                direction: "descending",
                                                            };
                                                        } else {
                                                            sorts.splice(configuredIndex, 1);
                                                        }
                                                        changeWorkView({ ...workView,
                                                            sorts });
                                                    } else {
                                                        const next = sort?.id !== column.id
                                                            ? { id: column.id,
                                                                direction: "ascending" as const }
                                                            : sort.direction === "ascending"
                                                                ? { id: column.id,
                                                                    direction: "descending" as const }
                                                                : null;
                                                        changeView({ sort: next, page: 1 });
                                                    }
                                                }}>
                                                {column.header}
                                                {workView && configuredIndex >= 0 && (
                                                    <span aria-hidden="true">
                                                        {configuredIndex + 1}
                                                    </span>
                                                )}
                                                <span aria-hidden="true">
                                                    {workView
                                                        ? !configuredSort ? "↕" :
                                                            configuredSort.direction ===
                                                                "ascending" ? "↑" : "↓"
                                                        : sort?.id !== column.id ? "↕" :
                                                            sort.direction === "ascending"
                                                                ? "↑" : "↓"}
                                                </span>
                                            </button>
                                        ) : column.header}
                                    </TableHead>
                                );
                            })}
                        </tr>
                    </thead>
                    <tbody>
                        {(remote?.status === "loading" ||
                            remote?.status === "error" ||
                            pageRows.length === 0) ? (
                            <tr>
                                <TableCell
                                    colSpan={columnCount}
                                    className="py-8 text-center text-muted"
                                >
                                    {remote?.status === "loading" ? (
                                        <span role="status">불러오는 중…</span>
                                    ) : remote?.status === "error" ? (
                                        <span role="alert">
                                            {remote.errorMessage ??
                                                "데이터를 불러오지 못했습니다."}
                                            {remote.onRetry && (
                                                <Button variant="outline"
                                                    className="ml-2"
                                                    onClick={remote.onRetry}>
                                                    다시 시도
                                                </Button>
                                            )}
                                        </span>
                                    ) : emptyMessage}
                                </TableCell>
                            </tr>
                        ) : groupedItems.map((item, index) => item.kind === "group"
                            ? (
                                <tr key={`group-${item.id}`} data-group-id={item.id}>
                                    <TableCell colSpan={columnCount}
                                        className="bg-surface-subtle font-medium">
                                        {item.label}
                                    </TableCell>
                                </tr>
                            ) : renderRow(item.item, index))}
                    </tbody>
                </Table>
            </div>
            <Pagination
                page={currentPage}
                pageSize={validPageSize}
                totalItems={remote?.totalItems ?? visibleRows.length}
                onPageChange={(next) => changeView({ page: next })}
                pageSizeOptions={pageSizeOptions}
                onPageSizeChange={(size) => {
                    changeView({ pageSize: size, page: 1 });
                }}
            />
        </div>
    );
}

export { DataTable, filterAndSortTableRows };
export type {
    DataTableProps, DataTableColumn, DataTableFilter,
    DataTableRemoteFilter,
    DataTableView, DataTableSort, DataTableRemote,
};
export type { WorkViewConfig, WorkViewSort };
